package com.coffeeshop.service;import com.coffeeshop.dto.DiscountCommands;import com.coffeeshop.model.DiscountModels;import com.coffeeshop.repository.DiscountRepository;import java.math.*;import java.util.*;public final class DiscountService{private static final Set<String>TYPES=Set.of("PERCENTAGE","FIXED_AMOUNT");private final DiscountRepository repository;public DiscountService(DiscountRepository r){repository=Objects.requireNonNull(r);}public List<DiscountModels.Discount>discounts(String search,Boolean active){return repository.find(search,active);}public long save(DiscountCommands.Save q){Objects.requireNonNull(q);String type=q.type()==null?"":q.type().toUpperCase(Locale.ROOT);if(!TYPES.contains(type))throw new IllegalArgumentException("Select a valid discount type.");if(q.value()==null||q.value().signum()<0)throw new IllegalArgumentException("Discount value cannot be negative.");BigDecimal value=q.value().setScale(4,RoundingMode.HALF_UP);if("PERCENTAGE".equals(type)&&value.compareTo(new BigDecimal("100"))>0)throw new IllegalArgumentException("Percentage cannot exceed 100.");if(q.validFrom()!=null&&q.validUntil()!=null&&!q.validUntil().isAfter(q.validFrom()))throw new IllegalArgumentException("Valid until must be after valid from.");if(q.id()!=null&&(q.version()==null||q.version().length==0))throw new IllegalArgumentException("Refresh this discount and try again.");return repository.save(new DiscountCommands.Save(q.id(),required(q.code(),50,"Discount code"),required(q.name(),150,"Discount name"),type,value,q.validFrom(),q.validUntil(),q.active(),q.version()));}public void setActive(DiscountModels.Discount d,boolean active){Objects.requireNonNull(d);repository.setActive(d.id(),active,d.version());}private static String required(String v,int m,String n){if(v==null||v.isBlank())throw new IllegalArgumentException(n+" is required.");String x=v.trim();if(x.length()>m)throw new IllegalArgumentException(n+" is too long.");return x;}}
